//! clang 19's (or, under [`ClangCompat::Clang22`], clang 22's) answers to
//! the feature-test hooks ([cpp.cond]/5, Table 23, and clang's `__has_*`
//! extensions): [`ClangFeatures`].
//!
//! The answers come from `features_table.rs`, generated by
//! `scripts/gen-features.sh`, which probes `clang++-19 -E` and
//! `clang++-22 -E` for every builtin, attribute, feature and keyword
//! spelling either clang knows, under each supported target and standard
//! and under each [`FeatureFlag`]. The clang 22 answers are stored as
//! deltas on clang 19's. Lookups are binary searches in sorted static
//! arrays; nothing is allocated per query. See `spec/pp.md` §"Feature
//! queries" and §"clang compatibility level" for the normative description.
//!
//! In C ([`ClangFeatures::with_c`]) the answers are those of the C++
//! standard the C standard lexes as, with the deltas of
//! `features_c_table.rs` (`scripts/gen-features-c.sh`, from `clang-19 -x c`
//! and `clang-22 -x c`) applied after the flag overlays, then each set
//! flag's C deltas (spec/pp.md §"Feature queries in C").

use std::cmp::Ordering;

use kiln_lex::{CStd, Std};

use crate::builtin::{FeatureQueries, TargetQuery};
use crate::options::ClangCompat;

#[path = "features_table.rs"]
mod table;

#[path = "features_c_table.rs"]
mod c_table;

pub use table::FeatureFlag;

/// A table entry: (key, value, mask of the configurations it holds in).
struct Entry(&'static str, u32, u16);

/// An answer that differs from the base table when a flag is set:
/// (flag, query, key, value, configuration mask).
struct Overlay(FeatureFlag, Kind, &'static str, u32, u16);

/// A clang 22 answer that replaces the base entry's:
/// (query, key, value, configuration mask).
struct Delta(Kind, &'static str, u32, u16);

/// A C answer that replaces the C++ one: (query, key, value, C
/// configuration mask, bit `target * 10 + std * 2 + gnu`).
struct CDelta(Kind, &'static str, u32, u32);

/// A C answer under a flag that replaces the prediction (the C++ answer
/// under the flag with the [`CDelta`]s applied): (flag, query, key, value,
/// C configuration mask).
struct CFlagDelta(FeatureFlag, Kind, &'static str, u32, u32);

/// The query a table answers. Declaration order is the overlay sort order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Kind {
    Feature,
    Extension,
    Builtin,
    ConstexprBuiltin,
    Attribute,
    DeclspecAttribute,
    CppAttribute,
    Keyword,
    /// `__has_c_attribute` (C deltas only).
    CAttribute,
}

/// The targets the tables were generated for, in configuration-bit order.
const TARGETS: [&str; 2] = ["aarch64", "x86_64"];

/// Standards in configuration-bit order (C++03 answers as C++98).
fn std_index(std: Std) -> u16 {
    match std {
        Std::Cxx98 | Std::Cxx03 => 0,
        Std::Cxx11 => 1,
        Std::Cxx14 => 2,
        Std::Cxx17 => 3,
        Std::Cxx20 => 4,
        Std::Cxx23 => 5,
        Std::Cxx26 => 6,
    }
}

/// Unscoped standard attributes kiln implements beyond clang 22's tables:
/// (minimum [`std_index`], name, `__has_cpp_attribute` value).
const KILN_CPP_ATTRIBUTES: &[(u16, &str, u32)] = &[
    // P2795R5 `[[indeterminate]]` (WP-448, spec/sema.md), C++26 only like
    // clang trunk's `LangOpts<"CPlusPlus26">` spelling.
    (6, "indeterminate", 202_403),
];

/// Unscoped standard attributes a later standard removes, which kiln
/// reports as 0 from that standard on at every compatibility level:
/// (first [`std_index`] without it, name).
const KILN_REMOVED_CPP_ATTRIBUTES: &[(u16, &str)] = &[
    // P3475R2 removes `[[carries_dependency]]` from C++26 (WP-743; GCC 16.1
    // answers 0 at C++26, clang 22 still 200809L).
    (6, "carries_dependency"),
];

/// A target triple, normalized as clang's `TargetInfo` sees it.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Triple {
    /// Index into [`TARGETS`].
    target: u16,
    arch: String,
    vendor: String,
    os: String,
    env: String,
}

impl Triple {
    /// `arch-vendor-os-env`, or `arch-os-env` with the vendor omitted
    /// (`x86_64-linux-gnu`). `None` unless the arch is aarch64/arm64 or
    /// `x86_64`/`amd64` and the OS is Linux with a GNU environment.
    fn parse(triple: &str) -> Option<Triple> {
        let mut parts: Vec<&str> = triple.split('-').collect();
        if parts.len() == 3 && parts[1].starts_with("linux") {
            parts.insert(1, "unknown");
        }
        let [arch, vendor, os, env] = parts[..] else {
            return None;
        };
        let target = match arch {
            "aarch64" | "arm64" => 0,
            "x86_64" | "amd64" => 1,
            _ => return None,
        };
        if !os.starts_with("linux") || env_kind(env) != Some(EnvKind::Gnu) {
            return None;
        }
        Some(Triple {
            target,
            arch: TARGETS[usize::from(target)].to_owned(),
            vendor: vendor.to_owned(),
            os: os.to_owned(),
            env: env.to_owned(),
        })
    }
}

/// The environments clang's triple parser tells apart that matter here.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EnvKind {
    Gnu,
    Other,
}

/// LLVM `Triple::parseEnvironment` restricted to the GNU family: the
/// parser takes the first listed prefix that matches, and only a plain
/// `gnu` prefix means `Triple::GNU`. `None` for an unknown environment.
fn env_kind(name: &str) -> Option<EnvKind> {
    const OTHER: [&str; 12] = [
        "eabihf",
        "eabi",
        "gnuabin32",
        "gnuabi64",
        "gnueabihft64",
        "gnueabihf",
        "gnueabi",
        "gnuf32",
        "gnuf64",
        "gnusf",
        "gnux32",
        "gnu_ilp32",
    ];
    if OTHER.iter().any(|p| name.starts_with(p)) || name.starts_with("code16") {
        return Some(EnvKind::Other);
    }
    if name.starts_with("gnut64") {
        return Some(EnvKind::Other);
    }
    if name.starts_with("gnu") {
        return Some(EnvKind::Gnu);
    }
    None
}

/// clang's [`FeatureQueries`] for one target, standard, set of driver
/// options and [`ClangCompat`] level (`ClangCompat::default()`, clang 22,
/// unless [`ClangFeatures::with_compat`] says otherwise).
///
/// `-march`/`-mcpu`/`-m<feature>` are not modeled by the tables:
/// `__has_builtin` answers for target builtins are those of the triple's
/// default CPU, except for the builtins of a [`TargetBuiltins`] hook
/// ([`ClangFeatures::with_target_builtins`]).
#[derive(Clone, Debug)]
pub struct ClangFeatures {
    triple: Triple,
    /// The configuration bit (`target * 7 + std`).
    bit: u16,
    /// Set flags the target supports, sorted and deduplicated.
    flags: Vec<FeatureFlag>,
    /// Whose answers.
    compat: ClangCompat,
    /// Feature-gated target builtins answered from the enabled features.
    target_builtins: Option<TargetBuiltins>,
    /// The `-fno-builtin-<name>` names, sorted (clang
    /// `LangOptions::NoBuiltinFuncs`): each library builtin among them
    /// answers 0, as `-fno-builtin` answers all of them (WP-808).
    no_builtin_fns: Vec<String>,
    /// The C configuration bit (`target * 10 + std * 2 + gnu`), 0 in C++.
    c_bit: u32,
}

/// Target builtins whose `__has_builtin` answer depends on the enabled
/// target features (clang `Builtin::Context::isBuiltinSupported` /
/// `evaluateRequiredTargetFeatures`; WP-558's NEON builtins): names
/// starting with `prefix` that `required` knows answer 1 exactly when
/// their required features hold.
#[derive(Clone, Debug)]
pub struct TargetBuiltins {
    /// The name prefix the hook covers (`__builtin_neon_`).
    pub prefix: &'static str,
    /// The required-features string of a builtin (`bf16,neon`: `,` is
    /// all of, `|` any of), `None` if there is no such builtin.
    pub required: fn(&str) -> Option<&'static str>,
    /// The enabled target features, sorted.
    pub enabled: Vec<String>,
}

impl TargetBuiltins {
    fn answer(&self, name: &str) -> Option<u32> {
        if !name.starts_with(self.prefix) {
            return None;
        }
        let req = (self.required)(name)?;
        // An x86 builtin without a required feature (WP-630).
        if req.is_empty() {
            return Some(1);
        }
        let on = |f: &str| self.enabled.binary_search_by(|e| e.as_str().cmp(f)).is_ok();
        Some(u32::from(req.split(',').all(|all| all.split('|').any(|f| on(f.trim())))))
    }
}

impl ClangFeatures {
    /// The answers for `triple` (`aarch64-unknown-linux-gnu`,
    /// `x86_64-unknown-linux-gnu`, or the same without the vendor) in
    /// `std` with `flags` set. Flags clang rejects for the target (the
    /// aarch64-only `-fptrauth-*`, x86_64-only `-fsanitize=numerical`) are
    /// ignored. `None` for any other target.
    pub fn new(triple: &str, std: Std, flags: &[FeatureFlag]) -> Option<ClangFeatures> {
        let triple = Triple::parse(triple)?;
        let bit = 1u16 << (triple.target * 7 + std_index(std));
        let mut flags: Vec<FeatureFlag> =
            flags.iter().copied().filter(|f| f.supported() & bit != 0).collect();
        flags.sort_unstable();
        flags.dedup();
        Some(ClangFeatures {
            triple,
            bit,
            flags,
            compat: ClangCompat::default(),
            target_builtins: None,
            no_builtin_fns: Vec::new(),
            c_bit: 0,
        })
    }

    /// These answers with the feature-gated target builtins of `t`.
    #[must_use]
    pub fn with_target_builtins(mut self, mut t: TargetBuiltins) -> ClangFeatures {
        t.enabled.sort_unstable();
        self.target_builtins = Some(t);
        self
    }

    /// These answers at compatibility level `compat`.
    #[must_use]
    pub fn with_compat(mut self, compat: ClangCompat) -> ClangFeatures {
        self.compat = compat;
        self
    }

    /// These answers in C standard `c` (`gnu`: the GNU dialect): the
    /// answers of the C++ standard these were made for (the one `c` lexes
    /// as, spec/driver.md "Language mode") with clang's C deltas applied.
    #[must_use]
    pub fn with_c(mut self, c: CStd, gnu: bool) -> ClangFeatures {
        let std = match c {
            CStd::C89 => 0,
            CStd::C99 => 1,
            CStd::C11 => 2,
            CStd::C17 => 3,
            CStd::C23 => 4,
        };
        self.c_bit = 1 << (u32::from(self.triple.target) * 10 + std * 2 + u32::from(gnu));
        self
    }

    /// The compatibility level.
    pub fn compat(&self) -> ClangCompat {
        self.compat
    }

    /// Whether the target is `x86_64` (else `aarch64`).
    pub fn is_x86_64(&self) -> bool {
        self.triple.target == 1
    }

    /// Whether the standard is C++26.
    pub fn is_cxx26(&self) -> bool {
        self.bit.trailing_zeros() % 7 == 6
    }

    /// [`ClangFeatures::new`] with the flags a clang command line sets:
    /// each option of [`FeatureFlag::options`], with `-fno-X` undoing `-fX`
    /// and vice versa, `-fsanitize=a,b` / `-fno-sanitize=a,b` lists,
    /// `-fsanitize-coverage=...`, `-fno-cxx-exceptions`, and
    /// `-std=gnu++NN` / `-std=c++NN` for [`FeatureFlag::GnuMode`]. Other
    /// arguments are ignored; the standard itself comes from `std`.
    pub fn from_args<S: AsRef<str>>(triple: &str, std: Std, args: &[S]) -> Option<ClangFeatures> {
        let mut set: Vec<FeatureFlag> = Vec::new();
        let mut names: Vec<String> = Vec::new();
        let mut freestanding = false;
        let mut toggle = |f: Option<FeatureFlag>, on: bool| {
            if let Some(f) = f {
                set.retain(|&g| g != f);
                if on {
                    set.push(f);
                }
            }
        };
        for arg in args {
            let arg = arg.as_ref();
            if let Some(list) = arg.strip_prefix("-fsanitize=") {
                for s in list.split(',') {
                    toggle(flag_with_option(&format!("-fsanitize={s}")), true);
                }
            } else if let Some(list) = arg.strip_prefix("-fno-sanitize=") {
                for s in list.split(',') {
                    toggle(flag_with_option(&format!("-fsanitize={s}")), false);
                }
            } else if let Some(v) = arg.strip_prefix("-fsanitize-coverage=") {
                toggle(flag_named("SanitizeCoverage"), !v.is_empty());
            } else if arg.starts_with("-fno-sanitize-coverage=") {
                toggle(flag_named("SanitizeCoverage"), false);
            } else if let Some(s) = arg.strip_prefix("-std=") {
                toggle(flag_named("GnuMode"), s.starts_with("gnu"));
            } else if arg == "-fno-cxx-exceptions" {
                toggle(flag_named("NoExceptions"), true);
            } else if arg == "-fcxx-exceptions" {
                toggle(flag_named("NoExceptions"), false);
            } else if arg == "-ffreestanding" || arg == "-fhosted" {
                // clang `Opts.NoBuiltin = -fno-builtin || Freestanding`:
                // `-fbuiltin` does not undo `-ffreestanding`.
                freestanding = arg == "-ffreestanding";
            } else if let Some(name) = arg.strip_prefix("-fno-builtin-") {
                names.push(name.to_owned());
            } else if let Some(f) = flag_with_option(arg) {
                toggle(Some(f), true);
            } else if let Some(rest) = arg.strip_prefix("-fno-") {
                toggle(flag_with_option(&format!("-f{rest}")), false);
            } else if let Some(rest) = arg.strip_prefix("-f") {
                toggle(flag_with_option(&format!("-fno-{rest}")), false);
            }
        }
        if freestanding {
            set.push(FeatureFlag::NoBuiltin);
        }
        names.sort_unstable();
        names.dedup();
        ClangFeatures::new(triple, std, &set).map(|mut f| {
            f.no_builtin_fns = names;
            f
        })
    }

    /// The flags in effect, in overlay order.
    pub fn flags(&self) -> &[FeatureFlag] {
        &self.flags
    }

    /// The answer of `kind` for `key` (already normalized).
    fn lookup(&self, kind: Kind, table: &[Entry], key: &str) -> u32 {
        self.lookup_at(kind, table, key, self.compat == ClangCompat::Clang22)
    }

    /// [`Self::lookup`] with clang 22's answers applied when `clang22`.
    fn lookup_at(&self, kind: Kind, table: &[Entry], key: &str, clang22: bool) -> u32 {
        let lo = table.partition_point(|e| e.0 < key);
        let mut v = 0;
        for e in table[lo..].iter().take_while(|e| e.0 == key) {
            if e.2 & self.bit != 0 {
                v = e.1;
            }
        }
        if clang22 {
            let deltas = table::COMPAT22;
            let lo = deltas.partition_point(|d| (d.0, d.1) < (kind, key));
            for d in deltas[lo..].iter().take_while(|d| d.0 == kind && d.1 == key) {
                if d.3 & self.bit != 0 {
                    v = d.2;
                }
            }
        }
        for &f in &self.flags {
            v = self.overlay(table::OVERLAYS, f, kind, key, v);
            if clang22 {
                v = self.overlay(table::COMPAT22_OVERLAYS, f, kind, key, v);
            }
        }
        if self.c_bit != 0 {
            let deltas = if clang22 { c_table::C22 } else { c_table::C19 };
            let lo = deltas.partition_point(|d| (d.0, d.1) < (kind, key));
            for d in deltas[lo..].iter().take_while(|d| d.0 == kind && d.1 == key) {
                if d.3 & self.c_bit != 0 {
                    v = d.2;
                }
            }
            let flag_deltas = if clang22 { c_table::C22_FLAGS } else { c_table::C19_FLAGS };
            for &f in &self.flags {
                let lo = flag_deltas.partition_point(|d| {
                    (d.0, d.1).cmp(&(f, kind)).then_with(|| d.2.cmp(key)) == Ordering::Less
                });
                for d in
                    flag_deltas[lo..].iter().take_while(|d| d.0 == f && d.1 == kind && d.2 == key)
                {
                    if d.4 & self.c_bit != 0 {
                        v = d.3;
                    }
                }
            }
        }
        v
    }

    /// `v` with the answers of `overlays` for flag `f` applied.
    fn overlay(&self, overlays: &[Overlay], f: FeatureFlag, kind: Kind, key: &str, v: u32) -> u32 {
        let lo = overlays.partition_point(|o| {
            (o.0, o.1).cmp(&(f, kind)).then_with(|| o.2.cmp(key)) == Ordering::Less
        });
        let mut v = v;
        for o in overlays[lo..].iter().take_while(|o| o.0 == f && o.1 == kind && o.2 == key) {
            if o.4 & self.bit != 0 {
                v = o.3;
            }
        }
        v
    }
}

/// Whether `name` is one of clang's library builtins (the `Builtins.td`
/// rows with the `f` attribute, which `-fno-builtin` turns off): the
/// names `__has_builtin` answers 0 for under [`FeatureFlag::NoBuiltin`],
/// with clang 22's additions when `clang22`. The `std` ones (`move`,
/// `forward`, ...) are among them (WP-808, sema's `no_builtin` names).
pub fn is_library_builtin(name: &str, clang22: bool) -> bool {
    let has = |overlays: &[Overlay]| {
        overlays
            .iter()
            .any(|o| o.0 == FeatureFlag::NoBuiltin && o.1 == Kind::Builtin && o.2 == name)
    };
    has(table::OVERLAYS) || (clang22 && has(table::COMPAT22_OVERLAYS))
}

/// A feature-query table, for [`table_keys`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FeatureTable {
    /// `__has_builtin`.
    Builtin,
    /// `__has_attribute`.
    Attribute,
    /// `__has_cpp_attribute` (scoped keys are `scope::name`).
    CppAttribute,
    /// `__has_declspec_attribute`.
    DeclspecAttribute,
}

/// Every key clang 19 or clang 22 answers nonzero for in some
/// configuration of `t`, sorted and deduplicated, for coverage tests
/// that walk clang's tables (WP-805: the attribute triage and builtin
/// lowering tests).
pub fn table_keys(t: FeatureTable) -> Vec<&'static str> {
    let (kind, base) = match t {
        FeatureTable::Builtin => (Kind::Builtin, table::BUILTIN),
        FeatureTable::Attribute => (Kind::Attribute, table::ATTRIBUTE),
        FeatureTable::CppAttribute => (Kind::CppAttribute, table::CPP_ATTRIBUTE),
        FeatureTable::DeclspecAttribute => (Kind::DeclspecAttribute, table::DECLSPEC_ATTRIBUTE),
    };
    let mut v: Vec<&'static str> = base.iter().filter(|e| e.1 != 0).map(|e| e.0).collect();
    v.extend(table::COMPAT22.iter().filter(|d| d.0 == kind && d.2 != 0).map(|d| d.1));
    v.sort_unstable();
    v.dedup();
    v
}

/// The flag whose first probed option is `option`.
fn flag_with_option(option: &str) -> Option<FeatureFlag> {
    FeatureFlag::ALL.iter().copied().find(|f| f.options().first() == Some(&option))
}

/// The flag named `name` (Debug spelling), if the table has it.
fn flag_named(name: &str) -> Option<FeatureFlag> {
    FeatureFlag::ALL.iter().copied().find(|f| format!("{f:?}") == name)
}

/// `__x__` -> `x` (clang `HasFeature`, `normalizeAttrName`).
fn strip_dunder(name: &str) -> &str {
    if name.len() >= 4 && name.starts_with("__") && name.ends_with("__") {
        &name[2..name.len() - 2]
    } else {
        name
    }
}

/// clang 22's `arm_acle.h` header builtins (`TARGET_HEADER_BUILTIN`,
/// `ARMACLE_H`), which kiln does not declare (WP-724): kiln ships clang
/// 19's `arm_acle.h`, which defines each as a macro or inline function
/// when `__has_builtin` denies it, so `__has_builtin` answers clang 19's
/// table for them at every compatibility level: 0, and kiln declares none
/// of them, in every mode kiln++ accepts. clang 19's 1 under
/// `-fms-extensions` (where they are LANGBUILTINs) is reachable only
/// through a library [`ClangFeatures`] built with that flag; kiln++
/// rejects `-fms-extensions` (spec/pp.md "Feature queries", WP-846).
const ACLE_HEADER_BUILTINS: &[&str] =
    &["__dmb", "__dsb", "__isb", "__sev", "__sevl", "__wfe", "__wfi", "__yield"];

impl FeatureQueries for ClangFeatures {
    fn has_feature(&self, name: &str) -> bool {
        self.lookup(Kind::Feature, table::FEATURE, strip_dunder(name)) != 0
    }

    fn has_extension(&self, name: &str) -> bool {
        self.lookup(Kind::Extension, table::EXTENSION, strip_dunder(name)) != 0
    }

    fn has_builtin(&self, name: &str) -> u32 {
        if let Some(v) = self.target_builtins.as_ref().and_then(|t| t.answer(name)) {
            return v;
        }
        if ACLE_HEADER_BUILTINS.contains(&name) {
            return self.lookup_at(Kind::Builtin, table::BUILTIN, name, false);
        }
        let v = self.lookup(Kind::Builtin, table::BUILTIN, name);
        if self.no_builtin_fns.binary_search_by(|n| n.as_str().cmp(name)).is_ok() {
            // `-fno-builtin-<name>` drops a library builtin the way
            // `-fno-builtin` does (clang `Builtin::Context::initializeBuiltins`).
            return self.overlay(table::OVERLAYS, FeatureFlag::NoBuiltin, Kind::Builtin, name, v);
        }
        v
    }

    fn has_constexpr_builtin(&self, name: &str) -> bool {
        self.lookup(Kind::ConstexprBuiltin, table::CONSTEXPR_BUILTIN, name) != 0
    }

    fn has_attribute(&self, name: &str) -> u32 {
        self.lookup(Kind::Attribute, table::ATTRIBUTE, strip_dunder(name))
    }

    fn has_cpp_attribute(&self, scope: Option<&str>, name: &str) -> u32 {
        // clang `normalizeAttrScopeName` / `normalizeAttrName`.
        let scope = scope.map(|s| match s {
            "__gnu__" => "gnu",
            "_Clang" => "clang",
            s => s,
        });
        match scope {
            None => {
                let name = strip_dunder(name);
                let std = self.bit.trailing_zeros() as u16 % 7;
                if KILN_REMOVED_CPP_ATTRIBUTES.iter().any(|&(from, n)| n == name && std >= from) {
                    return 0;
                }
                let v = self.lookup(Kind::CppAttribute, table::CPP_ATTRIBUTE, name);
                if v != 0 {
                    return v;
                }
                // Standard attributes kiln implements beyond clang 22, at
                // every compatibility level (like `KILN_FEATURES`).
                KILN_CPP_ATTRIBUTES
                    .iter()
                    .find(|&&(min, n, _)| n == name && std >= min)
                    .map_or(0, |&(_, _, v)| v)
            }
            Some(s) => {
                let name = if matches!(s, "gnu" | "clang") { strip_dunder(name) } else { name };
                let key = format!("{s}::{name}");
                self.lookup(Kind::CppAttribute, table::CPP_ATTRIBUTE, &key)
            }
        }
    }

    fn has_c_attribute(&self, scope: Option<&str>, name: &str) -> u32 {
        // clang `normalizeAttrScopeName` / `normalizeAttrName`, as for
        // `__has_cpp_attribute`.
        let scope = scope.map(|s| match s {
            "__gnu__" => "gnu",
            "_Clang" => "clang",
            s => s,
        });
        match scope {
            None => self.lookup(Kind::CAttribute, &[], strip_dunder(name)),
            Some(s) => {
                let name = if matches!(s, "gnu" | "clang") { strip_dunder(name) } else { name };
                self.lookup(Kind::CAttribute, &[], &format!("{s}::{name}"))
            }
        }
    }

    fn has_declspec_attribute(&self, name: &str) -> bool {
        self.lookup(Kind::DeclspecAttribute, table::DECLSPEC_ATTRIBUTE, name) != 0
    }

    fn is_keyword(&self, name: &str) -> bool {
        self.lookup(Kind::Keyword, table::KEYWORD, name) != 0
    }

    /// clang `isTargetArch` & co. (PPMacroExpansion.cpp) for a Linux GNU
    /// triple: names compare case-insensitively; an arch name matches if
    /// LLVM parses it to the target's arch (`aarch64`, `arm64`; `x86_64`,
    /// `x86_64h`, `amd64`; LLVM's ARM parser also accepts many suffixed
    /// spellings such as `aarch64v8a`, which are not modeled); an OS name
    /// matches if LLVM's prefix parse gives Linux (`linux*`); an
    /// environment if it gives GNU (`gnu*` except `gnueabi*`, `gnux32*`,
    /// ...). There is no Darwin target variant, so the `variant` queries
    /// are false.
    fn is_target(&self, query: TargetQuery, name: &str) -> bool {
        let lower = name.to_ascii_lowercase();
        let t = &self.triple;
        match query {
            TargetQuery::Arch => {
                let parsed = match lower.as_str() {
                    "aarch64" | "arm64" => Some(0),
                    "x86_64" | "x86_64h" | "amd64" => Some(1),
                    _ => None,
                };
                parsed == Some(t.target) || lower == t.arch
            }
            TargetQuery::Vendor => {
                let v = if t.vendor.is_empty() { "unknown" } else { t.vendor.as_str() };
                lower == v.to_ascii_lowercase()
            }
            TargetQuery::Os => lower.starts_with("linux") && t.os.starts_with("linux"),
            TargetQuery::Environment => {
                env_kind(&lower) == Some(EnvKind::Gnu) && env_kind(&t.env) == Some(EnvKind::Gnu)
            }
            TargetQuery::VariantOs | TargetQuery::VariantEnvironment => false,
        }
    }

    fn flt_eval_method(&self) -> i32 {
        table::FLT_EVAL_METHOD[usize::from(self.triple.target)]
    }
}
